        // Set up: deploy and initialize
        c.SetMinSum(0); // set initial MinSum to 0
        c.SetLogFile(address(0xdead)); // dummy log address
        c.Initialized();

        // Now the divergence: call SetMinSum(5) after init
        // In reference, this reverts; in mutant, it does nothing silently
        // To avoid revert in reference breaking our test, we capture via try/catch
        bool setMinSumSucceeded;
        try c.SetMinSum(5) {
            setMinSumSucceeded = true;
        } catch {
            setMinSumSucceeded = false;
        }
        // After this, MinSum in reference = 0, in mutant = 5

        // Fund and prepare a user
        address user = address(0x123);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.Put{value: 3 ether}(0); // balance = 3, unlockTime = now

        // Warp past unlockTime
        vm.warp(block.timestamp + 1);

        // Now try Collect(3) for that user
        vm.prank(user);
        bool collectSucceeded;
        try c.Collect(3 ether) {
            collectSucceeded = true;
        } catch {
            collectSucceeded = false;
        }

        // Reference: MinSum = 0 (since SetMinSum reverted), balance 3 >= 0, collect succeeds
        // Mutant: MinSum = 5 (since SetMinSum silently set it), balance 3 < 5, collect fails
        // Assert reference passes (collect succeeds) while mutant fails (collect fails)
        // The difference is that setMinSumSucceeded is false in reference, true in mutant.
        // But the observable divergence is in Collect behavior.
        // We assert: if setMinSumSucceeded (mutant), collect fails; if not (reference), collect succeeds.
