pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: minimal state to allow entry into Collect
        c.SetMinSum(0);
        // Deploy Log contract so LogFile.AddMessage doesn't revert
        address log = address(new Log());
        c.SetLogFile(log);
        c.Initialized();
        // Give some ether to the contract so call can succeed (but we want revert inside)
        vm.deal(address(c), 1 ether);
        // Actor with zero balance calls Collect(0) — the call inside will succeed (value=0) but then the else branch is taken?
        // Actually with balance=0, _s will be true for sending 0 wei, so LogFile.AddMessage executes.
        // To trigger the else branch, we need _s=false. That requires the call to fail.
        // The call can fail if the recipient reverts or if there's insufficient gas — simplest is to set msg.sender to a contract that reverts on receive.
        // But the spec says to observe only through public surface; we can use address(this) which is a contract and will revert on receive? No, Test contract can receive.
        // Instead, we make the call with _am=0 but msg.sender's receive() will succeed, so else not taken.
        // To force _s=false we need to send ether to a contract that doesn't have receive/fallback? But fallback is defined on C.
        // Actually the call is to msg.sender; if msg.sender is a contract with no receive, sending 0 wei should succeed? Actually sending 0 wei to a contract without receive should revert (since Solidity 0.8).
        // So we can set msg.sender to a contract with no receive/fallback to make the call fail.
        // Deploy a simple contract that reverts on receive:
        Rejector rejector = new Rejector();
        vm.deal(address(rejector), 0);
        vm.prank(address(rejector));
        // Now call Collect(0) from rejector
        bool ok;
        try c.Collect(0) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "Reference should revert on failing call");
    }
}

contract Log {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

contract Rejector {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}
